    public static void main(String[] args) {
        int floor = 0;
        int firstBasementIndex = -1;

        for (int i = 0; i < INPUT.length(); i++) {
            char c = INPUT.charAt(i);
            if (c == '(') {
                floor++;
            } else if (c == ')') {
                floor--;
            }

            // Check if we have entered the basement for the first time
            if (floor < 0 && firstBasementIndex == -1) {
                firstBasementIndex = i + 1; // +1 because we want a 1-based index
            }
        }

        System.out.println("Final floor: " + floor);
        System.out.println("First basement index: " + firstBasementIndex);


    }




